insert into public.site_sections (key, eyebrow, heading, intro, body, extra) values
  ('hero', 'US-based BPO & Digital Services', 'Your Partner in
Business Growth.', 'Prism Solutions helps businesses manage customer interactions, generate leads, arrange appointments, support sales, handle operational work and strengthen their digital presence.', '{}'::text[], '{"primaryCta":"Discuss Your Requirements","secondaryCta":"Explore Our Services","accent":["Growth."]}'::jsonb),
  ('about', 'About Prism Solutions', 'A US-based BPO and Digital Services company.', '', array['Prism Solutions is a US-based Business Process Outsourcing (BPO) and Digital Services company dedicated to helping businesses streamline operations, strengthen their market presence, enhance customer experiences, and achieve sustainable growth.', 'We bring together professional service delivery, practical digital capabilities, and dedicated human resources to support the day-to-day needs and growth objectives of our clients. Our solutions are designed around each organization’s requirements, operating environment, and customer expectations.']::text[], '{"principlesLine":"Our work is guided by three core principles: Quality, Commitment, and Performance. We value clear communication, dependable execution, and long-term working relationships.","pillars":[{"title":"Business process support","text":"Flexible operational and administrative assistance."},{"title":"Customer experience","text":"Professional engagement across customer touchpoints."},{"title":"Sales enablement","text":"Prospecting, qualification, appointment setting, and outreach."},{"title":"Digital growth","text":"Marketing, creative, and online presence support."}]}'::jsonb),
  ('values', 'Our Core Values', 'What guides our work.', '', '{}'::text[], '{}'::jsonb),
  ('services', 'Our Services', 'BPO and digital services from one partner.', 'Prism Solutions brings complementary services together so clients can access operational, customer-facing, sales, and digital support through one business partner.', '{}'::text[], '{}'::jsonb),
  ('why', 'Why Prism', 'Why businesses choose Prism Solutions.', '', '{}'::text[], '{}'::jsonb),
  ('industries', 'Industries', 'Where our services fit.', 'Our service mix is relevant to a range of organizations. The exact scope is adapted to each industry’s workflows, customer expectations, and compliance requirements.', '{}'::text[], '{"disclaimer":"Industry examples indicate potential areas of service fit and do not imply existing client engagements or specialist certifications."}'::jsonb),
  ('approach', 'Our Approach', 'How we work.', 'Five stages from first conversation to continuous improvement.', '{}'::text[], '{}'::jsonb),
  ('team', 'Our team', 'Meet the People Behind Prism', 'Behind every successful connection is a team that believes in understanding people, delivering with purpose and building lasting business relationships. Meet the people helping bring the Prism vision to life.', '{}'::text[], '{}'::jsonb),
  ('reviews', 'Reviews', 'Leave a review.', 'Share your experience with Prism Solutions. Every review is read by our team and appears here once it has been approved.', '{}'::text[], '{}'::jsonb),
  ('faq', 'FAQ', 'Questions, asked.', 'What businesses ask before getting in touch.', '{}'::text[], '{}'::jsonb),
  ('contact', 'Let’s connect', 'Let''s Build Something That Moves Your Business Forward.', 'Tell us about your business goals, operational challenges, or customer experience priorities. We would welcome the opportunity to understand your requirements and discuss how Prism Solutions may support your team.', '{}'::text[], '{"button":"Start a Conversation","fineprint":"Specific service scope, delivery arrangements, timelines, and commercial terms are confirmed through individual client discussions and written agreements."}'::jsonb),
  ('commitment', 'Our commitment', 'Built on Trust. Focused on Progress.', 'At Prism Solutions, we believe our success is measured by the success and satisfaction of our clients. We are committed to delivering more than services: we aim to build professional relationships, create growth opportunities, and provide dependable support that helps businesses move forward.', '{}'::text[], '{"items":[{"title":"Clear communication","text":"Agreed points of contact, updates, and escalation routes."},{"title":"Defined expectations","text":"Documented scope, deliverables, timelines, and responsibilities."},{"title":"Responsible handling","text":"Respect for client information and adherence to agreed access and data-handling procedures."},{"title":"Quality reviews","text":"Checks and feedback loops appropriate to the service being delivered."},{"title":"Continuous improvement","text":"Periodic review of workflows and opportunities to improve."}]}'::jsonb)
on conflict (key) do nothing;

update public.mission_vision set
  mission_label = 'Our Mission', mission_text = 'To become a trusted global business solutions partner by delivering high-quality BPO, digital marketing, customer support, and sales services that help businesses grow, operate efficiently, and build lasting customer relationships.', mission_highlights = array['trusted global business solutions partner', 'grow, operate efficiently, and build lasting customer relationships']::text[],
  vision_label = 'Our Vision', vision_text = 'To establish Prism Solutions as a globally recognized BPO and Digital Services company, empowering businesses across industries through innovative marketing strategies, exceptional customer experiences, professional outsourcing solutions, and reliable business partnerships.', vision_highlights = array['globally recognized BPO and Digital Services company', 'reliable business partnerships']::text[]
where id = 1 and mission_text = '' and vision_text = '';

do $$ begin
  if not exists (select 1 from public.services) then
