      ('appointment-setting', 'Appointment Setting', 'Appointment Setting', 'Customer & revenue operations', 'Prospect outreach, qualification, and calendar coordination for your sales team.', 'Engage prospects, qualify interest, coordinate calendars, and help sales teams create more productive conversations.', '', 20),
      ('sales-telemarketing', 'Sales & Telemarketing', 'Sales & Telemarketing', 'Customer & revenue operations', 'Outbound calling and campaigns that introduce your products and services.', 'Support outbound sales campaigns, product and service promotion, upselling, and cross-selling activities.', '', 30),
      ('lead-generation', 'Lead Generation', 'Lead Generation', 'Customer & revenue operations', 'Target market research, prospect identification, and lead qualification.', 'Research target markets, identify prospects, organize data, and support lead qualification and business development.', 'The process can be aligned with a defined ideal customer profile, target geography, industry, company size, and decision-maker criteria.', 40),
      ('back-office-support', 'Back-Office Support', 'Back-Office Support', 'Business operations', 'Data entry, documentation, and administrative coordination.', 'Provide administrative assistance, data entry, documentation, and data management support.', 'Designed to reduce administrative workload and help internal teams maintain organized, consistent processes.', 50),
