      ('digital-marketing', 'Digital Marketing', 'Digital Marketing', 'Digital growth', 'Social media, SEO, paid campaigns, content, design, and websites.', 'Build and strengthen digital presence through strategic marketing, creative content, campaign support, and online visibility.', 'We help businesses communicate their value, connect with relevant audiences, and maintain a consistent digital presence.', 70);
    insert into public.service_subcategories (service_id, title, detail, sort_order)
    select s.id, v.title, v.detail, v.ord from public.services s join (values
      ('customer-support', 'Inbound customer inquiries', 'Inbound inquiry handling and customer assistance.', 10),
      ('customer-support', 'Customer assistance', '', 20),
      ('customer-support', 'Outbound follow-ups', 'Outbound follow-up and customer communication.', 30),
      ('customer-support', 'Issue triage and escalation coordination', 'Basic issue triage, escalation coordination, and service updates.', 40),
