      ('appointment-setting', 'Appointment confirmation', '', 40),
      ('appointment-setting', 'Follow-up and sales-team handoff', 'Follow-up support and handoff notes for sales teams.', 50),
      ('sales-telemarketing', 'Outbound calling', 'Outbound calling and campaign execution.', 10),
      ('sales-telemarketing', 'Campaign execution', '', 20),
      ('sales-telemarketing', 'Product and service introductions', 'Product and service introductions based on approved scripts.', 30),
      ('sales-telemarketing', 'Upselling and cross-selling support', 'Upselling and cross-selling support where appropriate.', 40),
      ('sales-telemarketing', 'Prospect feedback and reporting', 'Prospect feedback capture and sales activity reporting.', 50),
      ('lead-generation', 'Target market research', 'Target market and account research.', 10),
      ('lead-generation', 'Prospect identification', 'Prospect identification and contact data organization.', 20),
      ('lead-generation', 'Lead qualification', 'Lead qualification against client-defined criteria.', 30),
      ('lead-generation', 'CRM and pipeline support', 'CRM updates, list hygiene, and pipeline support.', 40),
      ('lead-generation', 'Research summaries and reporting', 'Research summaries and agreed campaign reporting.', 50),
      ('back-office-support', 'Data entry', 'Data entry, formatting, and record maintenance.', 10),
      ('back-office-support', 'Document preparation', 'Document preparation and digital filing.', 20),
      ('back-office-support', 'Data management', 'Data management and information organization.', 30),
      ('back-office-support', 'Administrative coordination', 'Administrative coordination and task support.', 40),
      ('back-office-support', 'Process documentation', 'Process documentation and routine operational assistance.', 50),
      ('business-process-outsourcing', 'Project-based support', 'Defined scope, deliverables, timeline, and acceptance criteria.', 10),
      ('business-process-outsourcing', 'Dedicated resource support', 'Assigned personnel supporting agreed activities and working routines.', 20),
      ('business-process-outsourcing', 'Ongoing managed support', 'Recurring service delivery with agreed workflows, reporting, and review points.', 30),
      ('digital-marketing', 'Social Media Marketing and Management', 'Content planning, publishing coordination, community engagement, and account support.', 10),
      ('digital-marketing', 'Search Engine Optimization', 'Foundational on-page optimization, keyword research support, and content recommendations.', 20),
      ('digital-marketing', 'Paid Advertising and Campaign Management', 'Campaign setup support, audience targeting, creative coordination, and performance monitoring.', 30),
      ('digital-marketing', 'Content Creation and Marketing', 'Content calendars, copywriting, campaign messaging, and promotional content.', 40),
      ('digital-marketing', 'Brand Development and Online Visibility', 'Brand consistency, messaging, and digital presence support.', 50),
