do $$ begin
  if not exists (select 1 from public.faqs) then
    insert into public.faqs (question, answer, category, sort_order) values
      ('What services can Prism handle?', 'Customer support, appointment setting, sales and telemarketing, lead generation, back-office support, and Business Process Outsourcing, alongside digital marketing services such as social media, search engine optimization, paid advertising, content, design, and websites. You can engage support for a defined activity or for a broader set of related processes.', 'Services', 10),
      ('Can Prism provide dedicated customer support teams?', 'Yes, through dedicated resource support: assigned personnel supporting agreed activities and working routines. Customer support covers inbound inquiry handling and customer assistance, outbound follow-up and communication, basic issue triage and escalation coordination, and customer relationship support. Scope and responsibilities are defined with you before work begins.', 'Working together', 20),
      ('Does Prism handle inbound and outbound calls?', 'Prism handles inbound inquiries and customer assistance, outbound follow-up and customer communication, and outbound calling and campaign execution for sales and telemarketing. Product and service introductions follow approved scripts, and communication channels are defined with each client.', 'Services', 30),
      ('Can Prism support appointment setting and lead generation?', 'Yes. Appointment setting covers prospect outreach and initial engagement, lead qualification based on agreed criteria, calendar coordination and appointment confirmation, and follow-up support with handoff notes for sales teams. Lead generation covers target market and account research, prospect identification, qualification against client-defined criteria, CRM updates, and agreed campaign reporting.', 'Services', 40),
      ('How does onboarding work?', 'Once Prism understands your goals and processes and you have agreed scope, responsibilities, and success measures, onboarding covers access, training, and quality requirements. Delivery then begins, with progress shared through defined reporting.', 'Getting started', 50),
      ('Can services be tailored to a business?', 'Yes. Prism’s solutions are designed around each organization’s requirements, operating environment, and customer expectations, and service scope can be adjusted as business needs and workloads evolve.', 'Working together', 60),
      ('How is service quality monitored?', 'Through agreed workflows, review points, and performance monitoring, together with quality reviews and feedback loops appropriate to the service being delivered. Performance is reviewed periodically so practical improvements can be identified.', 'Working together', 70),
      ('How can a business request a proposal?', 'Use the contact form below, or email prismsolutions.pvt@gmail.com, with your business goals, operational challenges, or customer experience priorities. Prism welcomes the opportunity to understand your requirements and discuss how it can support your team. Scope, delivery arrangements, timelines, and commercial terms are confirmed through client discussions and written agreements.', 'Getting started', 80),
      ('What engagement models are available?', 'Project-based support with a defined scope, deliverables, timeline, and acceptance criteria; dedicated resource support with assigned personnel; and ongoing managed support with agreed workflows, reporting, and review points.', 'Working together', 90),
      ('How is client information handled?', 'With respect for client information and in line with the access and data-handling procedures agreed with you. Specific arrangements are confirmed with each client.', 'Getting started', 100);
  end if;
end $$;

update public.site_settings set
  seo_description = 'Prism Solutions is a US-based BPO and Digital Services company: customer support, sales and telemarketing, appointment setting, lead generation, back-office support and digital marketing from one partner.',
  footer_note = 'Specific service scope, delivery arrangements, timelines, and commercial terms are confirmed through individual client discussions and written agreements.',
  footer_marquee = array['Your Partner in Business Growth.', 'Quality', 'Commitment', 'Performance']::text[],
  content_seeded = true
where id = 1;
